 * Attribution: Créé par @ti-to sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function NeoBrutalismPage() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Neo-Brutalist Services</title>

    <style>
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;700&display=swap');

        body { 
            background: #0A192F; 
            color: #F8F8F8; 
            font-family: 'Space Grotesk', sans-serif;
        }
        .brutal-shadow { 
            box-shadow: 8px 8px 0 #00E0FF; 
            transition: transform 0.2s ease-in-out;
        }
        .brutal-shadow:hover {
            transform: translate(-4px, -4px);
            box-shadow: 12px 12px 0 #FF007A;
        }
        .btn {
            transition: all 0.3s;
        }
        .btn:hover {
            transform: scale(1.1);
        }
        .btn:active {
            transform: scale(0.9);
        }
        input, textarea {
            background: #1C1C1C;
            border: 2px solid #00E0FF;
            color: #F8F8F8;
            padding: 12px;
            width: 100%;
            font-size: 1rem;
        }
        input:focus, textarea:focus {
            border-color: #FF007A;
            outline: none;
        }
        .form-container {
            background: #111111;
            padding: 2rem;
            box-shadow: 8px 8px 0 #00E0FF;
        }
        .nav-menu {
            background: #111;
            box-shadow: 8px 8px 0 #00E0FF;
            padding: 16px;
        }
        .nav-link {
            padding: 12px 16px;
            border: 2px solid transparent;
            transition: all 0.3s ease-in-out;
        }
        .nav-link:hover {
            border-color: #FF007A;
            background: #00E0FF;
            color: #111;
            box-shadow: 4px 4px 0 #FF007A;
            transform: translate(-2px, -2px);
        }
    </style>
</head>
<body class="font-sans">
    <header class="fixed top-0 w-full z-10 nav-menu flex justify-between items-center p-6">
        <h1 class="text-4xl font-extrabold">⚡ Services</h1>
        <nav>
            <a href="#home" class="nav-link text-xl mx-4">Home</a>
            <a href="#services" class="nav-link text-xl mx-4">Services</a>
            <a href="#process" class="nav-link text-xl mx-4">Process</a>
            <a href="#contact" class="nav-link text-xl mx-4">Contact</a>
        </nav>
    </header>

    <section id="home" class="p-24 text-center mt-24">
        <h2 class="text-5xl font-bold brutal-shadow inline-block p-4">We Build Bold Websites</h2>
        <p class="mt-4 text-xl">High-performance, aesthetic, and brutally modern.</p>
        <a href="#contact" class="mt-6 inline-block bg-yellow-500 text-black text-xl px-6 py-3 brutal-shadow btn hover:bg-white">Get Started Now</a>
    </section>

    <section id="services" class="grid grid-cols-1 md:grid-cols-3 gap-6 p-12">
        <div class="p-6 border-4 border-white brutal-shadow">
            <h3 class="text-3xl font-bold">🚀 Fast Performance</h3>
            <p class="mt-2">Optimized for speed and efficiency.</p>
        </div>
        <div class="p-6 border-4 border-white brutal-shadow">
            <h3 class="text-3xl font-bold">🎨 Unique Design</h3>
            <p class="mt-2">Eye-catching layouts with brutalist aesthetics.</p>
        </div>
        <div class="p-6 border-4 border-white brutal-shadow">
            <h3 class="text-3xl font-bold">🔒 Secure & Scalable</h3>
            <p class="mt-2">Built with the latest security standards.</p>
        </div>
    </section>

    <section id="process" class="p-12 text-center">
        <h2 class="text-4xl font-bold">Our Process</h2>
        <p class="mt-4 text-xl">We take your ideas and turn them into reality through a seamless development process.</p>
        <div class="grid grid-cols-1 md:grid-cols-3 gap-6 p-12">
            <div class="p-6 border-4 border-white brutal-shadow">
                <h3 class="text-3xl font-bold">🔍 Discovery</h3>
                <p class="mt-2">Understanding your vision and goals.</p>
            </div>
            <div class="p-6 border-4 border-white brutal-shadow">
                <h3 class="text-3xl font-bold">⚙️ Development</h3>
                <p class="mt-2">Building fast, secure, and scalable websites.</p>
            </div>
            <div class="p-6 border-4 border-white brutal-shadow">
                <h3 class="text-3xl font-bold">🚀 Launch</h3>
                <p class="mt-2">Deploying and optimizing for success.</p>
            </div>
        </div>
        <a href="#contact" class="mt-6 inline-block bg-blue-500 text-black text-xl px-6 py-3 brutal-shadow btn hover:bg-white">Start Your Project Today</a>
    </section>

    <section id="contact" class="p-12 text-center">
        <h2 class="text-4xl font-bold">Get in Touch</h2>
        <p class="mt-2">Let's build something awesome together.</p>
        <div class="form-container max-w-md mx-auto mt-6">
            <!-- Form Starts Here -->

          <!-- This form uses the fabform backend service at https://fabform.io --->


            <form action="https://fabform.io/f/FORM_ID" method="POST">
                <!-- The hidden field below contains your form's unique identifier -->
                <input type="hidden" name="form" value="YOUR_FORM_IDENTIFIER">

                <!-- Name Field -->
                <label class="block text-lg font-bold mb-2">Name</label>
                <input type="text" name="name" placeholder="Your Name" class="mb-4" required>

                <!-- Email Field -->
                <label class="block text-lg font-bold mb-2">Email</label>
                <input type="email" name="email" placeholder="Your Email" class="mb-4" required>

                <!-- Message Field -->
                <label class="block text-lg font-bold mb-2">Message</label>
                <textarea name="message" rows="4" placeholder="Your Message" class="mb-4" required></textarea>

                <!-- Submit Button -->
                <button type="submit" class="mt-4 inline-block bg-red-500 text-black text-xl px-6 py-3 brutal-shadow btn hover:bg-white">Send Message</button>
            </form>
            <!-- Form Ends Here -->
        </div>
    </section>
</body>
</html>" }} />
  );
}
